# --- 1단계: 메서드 추출 ---

public class LegacyOrderService {

    public void order(Long productId) {
        Product product = findProduct(productId);
        int price = product.getPrice();
        sendMail(price);
        saveOrder(productId, price, now());
    }

    protected Product findProduct(Long id) { return new ProductDao().findById(id); }
    protected void sendMail(int price) { new MailSender().send(...); }
    protected void saveOrder(Long id, int price, LocalDateTime at) { ... }
    protected LocalDateTime now() { return LocalDateTime.now(); }
}

#   동작은 안 바뀌었다

#   그런데 아직 테스트가 없어서 확인할 방법이 없다

#   이 단계가 가장 위험하다
#   IDE 의 Extract Method 를 쓴다. 손으로 안 옮긴다

# --- 2단계: 테스트에서 상속 ---

class TestableOrderService extends LegacyOrderService {
    Product product;
    List<String> mails = new ArrayList<>();
    List<Order> saved = new ArrayList<>();
    LocalDateTime fixed = LocalDateTime.of(2026, 9, 9, 11, 0);

    @Override protected Product findProduct(Long id) { return product; }
    @Override protected void sendMail(int price) { mails.add("주문 발생: " + price); }
    @Override protected void saveOrder(Long id, int price, LocalDateTime at) {
        saved.add(new Order(id, price, at));
    }
    @Override protected LocalDateTime now() { return fixed; }
}

@DisplayName("주문하면 상품 가격으로 주문이 저장되고 메일이 나간다")
@Test
void order() {
    // given
    TestableOrderService service = new TestableOrderService();
    service.product = new Product(1L, "아메리카노", 4000);

    // when
    service.order(1L);

    // then
    assertThat(service.saved).hasSize(1)
            .extracting("price", "orderedAt")
            .containsExactly(tuple(4000, LocalDateTime.of(2026, 9, 9, 11, 0)));
    assertThat(service.mails).containsExactly("주문 발생: 4000");
}

