# --- 3단계: 제대로 주입 ---

public class OrderService {

    private final ProductRepository productRepository;
    private final MailSendClient mailSendClient;
    private final OrderRepository orderRepository;

    public void order(Long productId, LocalDateTime orderedAt) {
        Product product = productRepository.findById(productId).orElseThrow();
        mailSendClient.sendEmail("admin@cafekiosk.com",
                "주문 발생: " + product.getPrice() + "원");
        orderRepository.save(new Order(productId, product.getPrice(), orderedAt));
    }
}

#   6.8절의 인터페이스와 2.7절의 시각 파라미터다

#   테스트를 다시 쓴다

@ExtendWith(MockitoExtension.class)
class OrderServiceTest {
    @Mock ProductRepository productRepository;
    @Mock MailSendClient mailSendClient;
    @Mock OrderRepository orderRepository;
    @InjectMocks OrderService orderService;

    @Test
    void order() {
        given(productRepository.findById(1L))
                .willReturn(Optional.of(new Product(1L, "아메리카노", 4000)));

        orderService.order(1L, LocalDateTime.of(2026, 9, 9, 11, 0));

        verify(mailSendClient).sendEmail(any(), contains("4000"));
        verify(orderRepository).save(any());
    }
}

$ ./gradlew test --tests OrderServiceTest

